/* Pretendard 오프라인 글꼴 (TEAM 06 공용)
   - 파일로 열 때(file://) 일부 브라우저(Firefox 등)가 다른 폴더의 글꼴 파일을 막는 문제를 피하려고
     사이트에 쓰인 글자만 담은 Pretendard를 이 스크립트 안에 넣어 "PretendardEmbed" 이름으로 등록
   - 각 페이지 글꼴 순서: PretendardLocal(폴더의 원본 글꼴) → PretendardEmbed(이 파일) → 시스템 글꼴
   - 페이지에 새 글자를 넣었는데 Firefox에서 그 글자만 다르게 보이면 이 파일을 다시 만들면 됨
   - Pretendard: SIL Open Font License 1.1 */
(function(){
  window.__TEAM06_ASSETS = true;   // 사이트 폴더가 함께 열렸는지 확인용
  if (!("FontFace" in window) || !document.fonts) return;
  var F = {
    100: "",
    200: "",
    300: "",
    400: "",
    500: "",
    600: "",
    700: ""
  };
  Object.keys(F).forEach(function(w){
    try {
      var bin = atob(F[w]), buf = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
      document.fonts.add(new FontFace("PretendardEmbed", buf.buffer, { weight: String(w), style: "normal", display: "swap" }));
    } catch (e) { /* 지원하지 않으면 원래 글꼴 순서대로 표시 */ }
  });
})();
